-- 可追溯经济价格定义：商城逐店 SKU 与鱼市逐图/鱼种/档位/重量区间。
-- 初始商城行来自随包静态快照；鱼市行来自现有 RF4DB 玩家样本，不标记为官服抓包。
CREATE TABLE IF NOT EXISTS shop_price_def(
    store_id TEXT NOT NULL CHECK(length(store_id)>0),
    item_id TEXT NOT NULL CHECK(length(item_id)>0),
    silver INTEGER NOT NULL DEFAULT 0 CHECK(silver>=0),
    gold INTEGER NOT NULL DEFAULT 0 CHECK(gold>=0),
    stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),
    source TEXT NOT NULL CHECK(length(source)>0),
    source_ref TEXT NOT NULL DEFAULT '',
    PRIMARY KEY(store_id,item_id)
);

INSERT OR IGNORE INTO shop_price_def(store_id,item_id,silver,gold,stock,source,source_ref)
SELECT store_id,item_id,silver,gold,stock,'static_snapshot','server_data/static.sqlite3' FROM shop_item;

CREATE TABLE IF NOT EXISTS fish_market_price_def(
    map_key TEXT NOT NULL CHECK(length(map_key)>0),
    fish_key TEXT NOT NULL CHECK(length(fish_key)>0),
    grade INTEGER NOT NULL CHECK(grade BETWEEN 1 AND 4),
    weight_min_g INTEGER NOT NULL DEFAULT 0 CHECK(weight_min_g>=0),
    weight_max_g INTEGER NOT NULL DEFAULT 0 CHECK(weight_max_g>=0),
    silver_per_kg REAL NOT NULL CHECK(silver_per_kg>0),
    source TEXT NOT NULL CHECK(length(source)>0),
    source_ref TEXT NOT NULL DEFAULT '',
    CHECK(weight_max_g=0 OR weight_max_g>weight_min_g),
    PRIMARY KEY(map_key,fish_key,grade,weight_min_g)
);
CREATE INDEX IF NOT EXISTS idx_fish_market_price_lookup ON fish_market_price_def(map_key,fish_key,grade,weight_min_g);

